-- Reviewed bulk source staged for a separately audited Administrator import.
CREATE TABLE ubl_workflow_sources (sha256 text PRIMARY KEY,filename text NOT NULL,content bytea NOT NULL,records jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ubl_workflow_batches (id uuid PRIMARY KEY,source_sha256 text UNIQUE NOT NULL REFERENCES ubl_workflow_sources(sha256),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ubl_workflow_requests (id uuid PRIMARY KEY,batch_id uuid NOT NULL REFERENCES ubl_workflow_batches(id),source_key text NOT NULL,source_row integer NOT NULL,customer_id integer NOT NULL REFERENCES customers(id),site_id integer REFERENCES sites(id),branch_code text,site_name text NOT NULL,stage text NOT NULL,version integer NOT NULL DEFAULT 1,data jsonb NOT NULL,source jsonb NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(batch_id,source_key));
CREATE UNIQUE INDEX ubl_workflow_active_branch ON ubl_workflow_requests(customer_id,branch_code) WHERE branch_code IS NOT NULL AND stage NOT IN('Declined','Confirmed BOQ issued');
CREATE UNIQUE INDEX ubl_workflow_active_site ON ubl_workflow_requests(customer_id,site_id) WHERE site_id IS NOT NULL AND stage NOT IN('Declined','Confirmed BOQ issued');
CREATE TABLE ubl_workflow_events (id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES ubl_workflow_requests(id),version integer NOT NULL,action text NOT NULL,snapshot jsonb NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,version));
CREATE TABLE ubl_workflow_documents (id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES ubl_workflow_requests(id),kind text NOT NULL,version integer NOT NULL,snapshot jsonb NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,kind,version));
CREATE TABLE ubl_workflow_attachments (id uuid PRIMARY KEY,request_id uuid NOT NULL REFERENCES ubl_workflow_requests(id),kind text NOT NULL,filename text NOT NULL,mime text NOT NULL,sha256 text NOT NULL,content bytea NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,sha256,kind));
CREATE TABLE ubl_workflow_demand (request_id uuid PRIMARY KEY REFERENCES ubl_workflow_requests(id),mode text NOT NULL CHECK(mode IN('Provisional','Confirmed')),document_id uuid NOT NULL REFERENCES ubl_workflow_documents(id));
CREATE UNIQUE INDEX ubl_workflow_po_number ON ubl_workflow_requests(customer_id,(data->>'poNumber')) WHERE data->>'poNumber' IS NOT NULL;
CREATE UNIQUE INDEX ubl_workflow_job_number ON ubl_workflow_requests((data->>'ipoNumber')) WHERE data->>'ipoNumber' IS NOT NULL;
CREATE TRIGGER immutable_ubl_workflow_source BEFORE UPDATE OR DELETE ON ubl_workflow_sources FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_ubl_workflow_batch BEFORE UPDATE OR DELETE ON ubl_workflow_batches FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_ubl_workflow_event BEFORE UPDATE OR DELETE ON ubl_workflow_events FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_ubl_workflow_document BEFORE UPDATE OR DELETE ON ubl_workflow_documents FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_ubl_workflow_attachment BEFORE UPDATE OR DELETE ON ubl_workflow_attachments FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
